CSS['list']=r'''
.list[data-el="meridian-deck-list"]{display:flex;flex-direction:column;justify-content:center;gap:var(--gap-sm);padding:var(--gap-sm);margin:0;counter-reset:meridian-item}.list[data-el="meridian-deck-list"]>.item{position:relative;display:grid;grid-template-columns:var(--gap) minmax(0,1fr);align-content:center;gap:var(--gap-sm);padding:var(--gap-sm) 0;min-width:0;counter-increment:meridian-item}.list[data-el="meridian-deck-list"]>.item::before{content:"";grid-column:1;grid-row:1;width:5px;height:5px;border-radius:50%;background:var(--a1-7);align-self:center;justify-self:center}.list[data-el="meridian-deck-list"]>.item>.name{grid-column:2;margin:0;font-size:clamp(var(--type-14),4.1cqw,var(--type-22));font-weight:var(--name-weight);line-height:var(--name-line);color:var(--n-7)}.list[data-el="meridian-deck-list"]>.item>.note{grid-column:2;margin:0;font-size:clamp(var(--type-12),3.4cqw,var(--type-18));line-height:var(--body-line);color:var(--n-7)}.list[data-el="meridian-deck-list"]>.item>.mark{grid-column:1;grid-row:1 / span 2;display:grid;place-items:center;color:var(--a1-7)}.list[data-el="meridian-deck-list"]>.item>.mark>.icon{width:24px;height:24px}.list[data-el="meridian-deck-list"]>.item:has(>.mark)::before{content:none}.list[data-el="meridian-deck-list"].check>.item::before{width:14px;height:8px;border-radius:0;background:none;border-left:2px solid var(--a1-7);border-bottom:2px solid var(--a1-7);rotate:-45deg}.list[data-el="meridian-deck-list"].divided>.item{border-bottom:var(--stroke) solid var(--n-4);padding:var(--gap)}.list[data-el="meridian-deck-list"].num>.item{grid-template-columns:min(13cqw,56px) minmax(0,1fr);column-gap:var(--gap);padding-left:0}.list[data-el="meridian-deck-list"].num>.item::before{content:counter(meridian-item,decimal-leading-zero);width:min(11cqw,50px);height:min(11cqw,50px);background:var(--a1);color:var(--a1-on);font-size:var(--type-18);font-weight:var(--label-weight);line-height:var(--label-line);display:grid;place-items:center;border-radius:999px}.list[data-el="meridian-deck-list"].num.divided>.item{flex:1;background:var(--n-1);border:0;padding-right:var(--gap);border-radius:var(--radius-sm)}
@container (max-height:180px){.list[data-el="meridian-deck-list"]>.item{padding:0}.list[data-el="meridian-deck-list"]>.item>.name{font-size:var(--type-14)}.list[data-el="meridian-deck-list"]>.item>.note{font-size:var(--type-12)}}
@container (max-width:340px){.list[data-el="meridian-deck-list"]>.item>.name{font-size:var(--type-16)}.list[data-el="meridian-deck-list"]>.item>.note{font-size:var(--type-12)}}
'''
common=lambda leaf:('[data-el="meridian-deck-'+leaf+'"]{box-sizing:border-box;position:relative;min-width:0;min-height:0;container-type:size;font-family:var(--font-body);font-size:var(--type-20);font-weight:var(--body-weight);line-height:var(--body-line);letter-spacing:var(--body-track);color:var(--ink)}\n[data-el="meridian-deck-'+leaf+'"] *{box-sizing:border-box}\n[data-el="meridian-deck-'+leaf+'"] .icon{display:inline-block;width:48px;height:48px}\n')
for leaf,body in CSS.items():(C/'elements'/leaf/'element.css').write_text(common(leaf)+body)
print('Fresh base CSS written:',', '.join(CSS))
